/**
 * Hero
 */
class Hero extends GameEntity {
  /**
   * Creates a new astronaut / hero.
   * @param {number=} x
   * @param {number=} y
   * @param {number=} z
   */
  constructor(x, y, z) {
    super(x, y, z);
    this.bounciness = 0.01;
    this.fuel = 100;
    this.jetpack = false;
    this.collisionContactMask = 0;
    this.cornerLockTime = -1;
    this.cornerDescentArmed = false;
  }

  /**
   * Arms the reduced landing envelope after a jetpack release.
   */
  armCornerDescent() {
    this.cornerDescentArmed = true;
    this.collisionContactMask =
        Math.abs(this.velocity[0]) >= Math.abs(this.velocity[2]) ? 1 : 2;
  }

  /**
   * Starts a fresh collision manifold for the frame.
   */
  beginCollisionFrame() {
    if (!this.cornerDescentArmed) {
      this.collisionContactMask = 0;
      this.cornerLockTime = -1;
    }
  }

  /**
   * Returns the radius used by platform collision checks.
   * @return {number}
   */
  collisionRadius() {
    return this.cornerDescentArmed && this.velocity[1] < 0 ? 0.28 : 0.7;
  }

  /**
   * Records a resolved horizontal contact axis.
   * @param {number} axis
   */
  recordCollisionAxis(axis) {
    this.collisionContactMask |= axis;
    if (this.collisionContactMask === 3 && this.cornerDescentArmed) {
      this.cornerLockTime = gameTime;
    }
  }

  /**
   * Whether horizontal movement is temporarily pinned by a corner contact.
   * @return {boolean}
   */
  isCornerLocked() {
    return this.cornerLockTime >= 0 && this.cornerDescentArmed;
  }

  /**
   * Renders the player model.
   * @override
   */
  render() {
    let leftArmRotationX = 0.0;
    let leftArmRotationZ = 1.2;
    let rightArmRotationX = 0.0;
    let rightArmRotationZ = -1.2;
    let leftLegRotationX = 0;
    let rightLegRotationX = 0;

    if (!this.isGrounded() || gameState === GameState.AFTER_LEVEL) {
      // Jumping = arms up
      leftArmRotationZ = -0.5;
      rightArmRotationZ = 0.5;
    } else if (this.accelerating) {
      // Running = arms back
      const r = (gameTime % 0.8) / 0.8 * 2 * Math.PI;
      rightLegRotationX = leftArmRotationX = 0.07 * Math.hypot(this.velocity[0], this.velocity[2]) * Math.sin(r);
      rightArmRotationX = leftLegRotationX = -leftArmRotationX;
      leftArmRotationZ = 1.2;
      rightArmRotationZ = -1.2;
    }

    // Draw face
    {
      const m = this.createSphere(COLOR_ORANGE);
      mat4.translate(m, m, vec3.fromValues(0, 1.8, 0));
      mat4.scale(m, m, vec3.fromValues(0.38, 0.38, 0.38));
    }

    // Draw helmet
    {
      const m = this.createSphere(COLOR_WHITE);
      mat4.translate(m, m, vec3.fromValues(0, 1.8, -0.08));
      mat4.scale(m, m, vec3.fromValues(0.45, 0.5, 0.38));
    }

    // Draw stomach
    {
      const m = this.createSphere(COLOR_WHITE);
      mat4.translate(m, m, vec3.fromValues(0, 1.05, 0));
      mat4.scale(m, m, vec3.fromValues(0.3, 0.47, 0.27));
    }

    // Draw left jetpack
    {
      const m = this.createSphere(COLOR_DARK_SILVER);
      mat4.translate(m, m, vec3.fromValues(-0.12, 1.2, -0.35));
      mat4.scale(m, m, vec3.fromValues(0.15, 0.32, 0.15));
    }

    // Draw right jetpack
    {
      const m = this.createSphere(COLOR_DARK_SILVER);
      mat4.translate(m, m, vec3.fromValues(0.12, 1.2, -0.35));
      mat4.scale(m, m, vec3.fromValues(0.15, 0.32, 0.15));
    }

    if (this.jetpack) {
      const m = this.createSphere(0xFF00A0FF);
      mat4.translate(m, m, vec3.fromValues(0, 0.9, -0.35));
      mat4.scale(m, m, vec3.fromValues(0.2, 0.2, 0.2));
      addLight(vec3.fromValues(this.pos[0], this.pos[1]+1, this.pos[2]), vec3.fromValues(1, 0.75, 0));
    }

    // Draw left arm
    {
      const m = this.createSphere(COLOR_WHITE);
      mat4.translate(m, m, vec3.fromValues(-.3, 1.4, 0));
      mat4.rotateX(m, m, leftArmRotationX);
      mat4.rotateZ(m, m, leftArmRotationZ);
      mat4.translate(m, m, vec3.fromValues(-.4, 0, 0));
      mat4.scale(m, m, vec3.fromValues(0.4, 0.16, 0.16));
    }

    // Draw right arm
    {
      const m = this.createSphere(COLOR_WHITE);
      mat4.translate(m, m, vec3.fromValues(0.3, 1.4, 0));
      mat4.rotateX(m, m, rightArmRotationX);
      mat4.rotateZ(m, m, rightArmRotationZ);
  for (let i = entities.length - 1; i >= 0; i--) {
    const entity = entities[i];
    if (entity !== player && entity.health <= 0) {
      entities.splice(i, 1);
      continue;
    }
    if (entity.rendered) {
      entity.setupTransformMatrix();
      entity.render();
    }
  }
}

/**
 * Player died.
 */
function playerDie() {
  playMusic(deathSongData);
  stopJetpackSound();
  setMenu(deathScreen);
}

let jetpackWasActive = false;

/**
 * Handles player input.
 */
function handleInput() {
  player.accelerating = false;

  if (gameState !== GameState.AFTER_LEVEL && gameState !== GameState.CREDITS) {
    if (isKeyDown(KEY_UP) || isKeyDown(KEY_W)) {
      player.velocity[2] += dt * ACCELERATION;
      player.accelerating = true;
    }
    if (isKeyDown(KEY_DOWN) || isKeyDown(KEY_S)) {
      player.velocity[2] -= dt * ACCELERATION;
      player.accelerating = true;
    }
    if (isKeyDown(KEY_LEFT) || isKeyDown(KEY_A)) {
      player.velocity[0] -= dt * ACCELERATION;
      player.accelerating = true;
    }
    if (isKeyDown(KEY_RIGHT) || isKeyDown(KEY_D)) {
      player.velocity[0] += dt * ACCELERATION;
      player.accelerating = true;
    }
    if ((isKeyDown(KEY_X) || isKeyDown(KEY_SHIFT)) && player.fuel > 0) {
      // Jetpack
      player.velocity[1] += dt * 60;
      player.jetpack = true;
      player.fuel = Math.max(0, player.fuel - dt * 20);
      createJetpackParticles();
    } else {
      player.jetpack = false;
    }
    if (jetpackWasActive && !player.jetpack && player.velocity[1] > 0) {
      player.armCornerDescent();
    }
    jetpackWasActive = player.jetpack;
    if (player.jetpack && !jetpackSound) {
      startJetpackSound();
    }
    if (!player.jetpack && jetpackSound) {
      stopJetpackSound();
    }
    if (player.isGrounded() && (keys[KEY_Z].downCount === 1 || keys[KEY_SPACE].downCount === 1)) {
      player.jump();
    }
    if (isKeyPressed(KEY_R)) {
      playerDie();
    }
    if (isKeyPressed(KEY_M)) {
      toggleBackgroundMusic();
    }
  }
}

/**
 * Creates jetpack particles.
 */
function createJetpackParticles() {
  if (Math.random() < 0.3) {
    const blast = new Particle();
    blast.size = 0.2;
    blast.velocity[1] = (gameState === GameState.AFTER_LEVEL || gameState === GameState.CREDITS) ? -10 : -0.3;
    vec3.copy(blast.pos, player.pos);
    blast.pos[0] -= 0.3 * Math.sin(player.yaw);
    blast.pos[1] += 0.8;
    blast.pos[2] -= 0.3 * Math.cos(player.yaw);
    entities.push(blast);
  }
}

/**
 * Updates everything.
 */
function updateWorld() {
  if (Math.random() < 0.02) {
    const floaty = new Particle();
    floaty.size = 0.08;
    floaty.velocity[1] = 1;
    vec3.copy(floaty.pos, player.pos);
    floaty.pos[0] += (Math.random() - 0.5) * 30.0;
    floaty.pos[2] += (Math.random() - 0.5) * 30.0;
    entities.push(floaty);
  }

  if (gameTime - lastCoinTime > 1.0) {
    coinSequence = 0;
  }

  for (let i = 0; i < entities.length; i++) {
    entities[i].update();
  }

  player.beginCollisionFrame();
  const playerWasAlive = player.health > 0;

  for (let i = 0; i < entities.length; i++) {
    for (let j = 0; j < entities.length; j++) {
      if ((entities[i] instanceof Platform) && !(entities[j] instanceof Platform)) {
        const platform = /** @type {!Platform} */ (entities[i]);
        const actor = entities[j];
        // Need actor size
        // Assume actor is a cylinder
        // Assume radius 1.0 and height 3.0
        // actor.pos represents center of feet
        const actorX = actor.pos[0];
        const actorY = actor.pos[1];
        const actorZ = actor.pos[2];
        const projectile = actor instanceof Particle && actor.projectile > 0;
        const actorRadius = projectile ? 0.1 :
            (actor instanceof Hero ? actor.collisionRadius() : 0.7);
        const actorHeight = projectile ? 0.1 : 2.5;

        const platformMinX = platform.pos[0] - platform.scale[0] - actorRadius;
        const platformMinY = platform.pos[1] - platform.scale[1];
        const platformMinZ = platform.pos[2] - platform.scale[2] - actorRadius;

        const platformMaxX = platform.pos[0] + platform.scale[0] + actorRadius;
        const platformMaxY = platform.pos[1] + platform.scale[1];
        const platformMaxZ = platform.pos[2] + platform.scale[2] + actorRadius;

        const graceY = 1.0;

        if (actorX > platformMinX && actorX < platformMaxX && actorZ > platformMinZ && actorZ < platformMaxZ) {
          if (projectile && actorY < platformMaxY && actorY > platformMinY) {
            // Destroy the projectile
