        'src/music.js',
        'src/constants.js',
        'src/colors.js',
        'src/hud.js',
        'src/menu.js',
        'src/mapgen.js',
        'src/index.js',
        'src/game_api.js',
      ],
      js_output_file: 'dist/index.js',
    });

    closureCompiler.run((exitCode, stdOut, stdErr) => {
      if (stdOut) {
        console.log(stdOut.trim());
      }
      if (exitCode === 0) {
        resolve();
      } else {
        reject(stdErr.trim());
      }
    });
  });
}

/**
 * Updates the JS file in place using property shortcuts.
 * @return {Promise}
 */
function compressStandardProperties() {
  return new Promise((resolve, reject) => {
    let js = fs.readFileSync('./dist/index.js', {encoding: 'utf8', flag: 'r'});

    const buildShortcut = (name) => name.substr(0, 3) + name.substr(-3) + (name[name.length - 8] || '_');
    const tokens = [
      'bindTexture',
      'texParameteri',
      'enableVertexAttribArray',
      'bufferData',
      'bindVertexArray',
      'bindBuffer',
      'vertexAttribPointer',
      'uniformMatrix4fv',
      'activeTexture',
      // 'framebufferTexture2D',
      // 'getUniformLocation',
      // 'createVertexArray',
    ];

    for (const token of tokens) {
      js = js.replaceAll(token, buildShortcut(token));
    }

    fs.writeFileSync('./dist/index.js', js);
    resolve();
  });
}

