/**
 * Updates keyboard state.
 */
const updateKeys = () => {
  anyKey.down = false;
  keys.forEach((k) => {
    if (k.down) {
      anyKey.down = true;
      k.upCount = 0;
      k.downCount++;
    } else {
      k.upCount++;
      k.downCount = 0;
    }
  });

  if (anyKey.down) {
    anyKey.upCount = 0;
    anyKey.downCount++;
  } else {
    anyKey.upCount++;
    anyKey.downCount = 0;
  }
};

/**
 * Resets keyboard to all keys unpressed.
